"""L1 in-memory state plus the background daemon that refreshes it.The rule this enforces: the orchestrator's hot path never awaits a bookmaker.Account state is served from memory in constant time, and a separate daemonabsorbs all the latency, flakiness and rate limits of the real adapters.Concurrency model-----------------Entries hold **frozen** Pydantic models and are replaced by whole-objectassignment, never mutated in place. A reader therefore observes either the oldsnapshot or the new one, never a torn half-updated view, and reads require nolock at all. The lock exists only to serialise writers so two concurrentrefreshes of the same bookmaker cannot interleave their bookkeeping.Staleness policy----------------Stale entries are served, not withheld, and are labelled with their age. TheTwin already refuses to size against a stale snapshot via its own``max_account_state_age_seconds`` gate. Having the cache also refuse wouldduplicate the policy in two places and guarantee they eventually disagree."""from __future__ import annotationsimport asyncioimport contextlibimport randomimport timefrom collections.abc import Mapping, Sequencefrom dataclasses import dataclassfrom datetime import datetimefrom typing import Final, Generic, TypeVarimport structlogfrom pydantic import BaseModel, ConfigDict, Fieldfrom betdoc.application.ports.intelligence_clients import (    AccountStateAdapter,    AccountUnavailableError,    IntelligenceError,    ReconciliationBreachError,    StaleAccountStateError,    TransientIntelligenceError,)from betdoc.domain.intelligence.account_models import (    AccountState,    BetRecord,    BettorProfile,    LinkedBookmaker,    utc_now,)from betdoc.domain.intelligence.news_models import ProbabilityModifier__all__ = [    "AccountRefreshDaemon",    "InMemoryStateStore",    "RefreshConfig",    "RefreshHealth",    "StateEntry",]_log: Final[structlog.stdlib.BoundLogger] = structlog.get_logger(    component="adapters.cache.state_store")ValueT = TypeVar("ValueT")@dataclass(frozen=True, slots=True)class StateEntry(Generic[ValueT]):    """A cached value with the two clocks needed to reason about it.    ``refreshed_at`` is wall clock, used for user-facing age and for the Twin's    staleness gate. ``refreshed_monotonic`` is monotonic, used for refresh    scheduling, because an NTP step must never make the daemon think it just    refreshed or that it is hours overdue.    """    value: ValueT    refreshed_at: datetime    refreshed_monotonic: float    refresh_count: int = 0    def age_seconds(self, *, now: datetime | None = None) -> float:        return ((now or utc_now()) - self.refreshed_at).total_seconds()    def is_stale(self, max_age_seconds: float, *, now: datetime | None = None) -> bool:        return self.age_seconds(now=now) > max_age_seconds@dataclass(slots=True)class RefreshHealth:    """Per-adapter refresh health, driving backoff and observability."""    bookmaker: LinkedBookmaker    consecutive_failures: int = 0    total_refreshes: int = 0    total_failures: int = 0    last_error: str | None = None    last_success_monotonic: float | None = None    is_quarantined: bool = False    def snapshot(self) -> dict[str, int | str | bool | None]:        return {            "bookmaker": self.bookmaker.value,            "consecutive_failures": self.consecutive_failures,            "total_refreshes": self.total_refreshes,            "total_failures": self.total_failures,            "last_error": self.last_error,            "is_quarantined": self.is_quarantined,        }class RefreshConfig(BaseModel):    """Polling cadence and failure policy for the refresh daemon."""    model_config = ConfigDict(frozen=True, extra="forbid", validate_default=True)    interval_seconds: float = Field(        default=30.0,        gt=0.0,        le=3_600.0,        description="Base cadence per adapter, drift-corrected each cycle.",    )    jitter_fraction: float = Field(        default=0.15,        ge=0.0,        le=0.5,        description=(            "Randomised fraction of the interval. Without jitter, every "            "adapter polls on the same tick after a restart, producing a "            "synchronised burst against every venue simultaneously."        ),    )    max_backoff_seconds: float = Field(default=300.0, gt=0.0, le=3_600.0)    quarantine_after_failures: int = Field(        default=10,        ge=1,        le=100,        description=(            "Consecutive failures after which polling drops to the backoff "            "ceiling. Hammering a restricted account accelerates the "            "restriction, so persistent failure must slow down, not persist."        ),    )    fetch_timeout_seconds: float = Field(default=10.0, gt=0.0, le=120.0)    include_active_bets: bool = Field(        default=True,        description="Also refresh open bets, the authoritative exposure source.",    )class InMemoryStateStore:    """L1 cache satisfying the orchestrator's ``StateProvider`` protocol.    Holds account snapshots per bookmaker, one bettor profile per id, active    news modifiers, and today's realized P&L per bookmaker. Every stored value    is a frozen domain model, so nothing handed out can be mutated by a caller.    """    __slots__ = (        "_accounts",        "_active_bets",        "_lock",        "_modifiers",        "_profiles",        "_realized_pnl_today_paise",    )    def __init__(self) -> None:        self._accounts: dict[LinkedBookmaker, StateEntry[AccountState]] = {}        self._active_bets: dict[LinkedBookmaker, StateEntry[tuple[BetRecord, ...]]] = {}        self._profiles: dict[str, StateEntry[BettorProfile]] = {}        self._modifiers: tuple[ProbabilityModifier, ...] = ()        self._realized_pnl_today_paise: dict[LinkedBookmaker, int] = {}        self._lock = asyncio.Lock()    # -------------------------------- reads ------------------------------- #    async def get_account_state(self, bookmaker: LinkedBookmaker) -> AccountState | None:        """Constant-time read. No lock, no I/O, no blocking.        Safe without a lock because ``dict`` lookup is atomic under the GIL and        the stored model is immutable, so the reference obtained is a complete,        self-consistent snapshot.        """        entry = self._accounts.get(bookmaker)        return entry.value if entry is not None else None    async def get_profile(self, profile_id: str) -> BettorProfile | None:        entry = self._profiles.get(profile_id)        return entry.value if entry is not None else None    async def get_active_modifiers(        self, *, now: datetime | None = None    ) -> tuple[ProbabilityModifier, ...]:        """Only modifiers that have not fully decayed.        Filtering here keeps expired modifiers out of the Twin entirely, so a        forgotten stale list cannot silently suppress stakes forever.        """        moment = now or utc_now()        return tuple(modifier for modifier in self._modifiers if modifier.is_active(now=moment))    async def get_realized_pnl_today_paise(self, bookmaker: LinkedBookmaker) -> int:        return self._realized_pnl_today_paise.get(bookmaker, 0)    async def get_active_bets(self, bookmaker: LinkedBookmaker) -> tuple[BetRecord, ...]:        entry = self._active_bets.get(bookmaker)        return entry.value if entry is not None else ()    def account_entry(self, bookmaker: LinkedBookmaker) -> StateEntry[AccountState] | None:        """Entry including its timestamps, for health reporting."""        return self._accounts.get(bookmaker)    def account_age_seconds(        self, bookmaker: LinkedBookmaker, *, now: datetime | None = None    ) -> float | None:        entry = self._accounts.get(bookmaker)        return None if entry is None else entry.age_seconds(now=now)    @property    def is_warm(self) -> bool:        """Whether at least one account and one profile are populated.        The orchestrator skips batches until this is true, which is why a cold        start produces skipped batches rather than sized bets against ``None``.        """        return bool(self._accounts) and bool(self._profiles)    # -------------------------------- writes ------------------------------ #    async def set_account_state(self, state: AccountState) -> None:        """Replace a snapshot atomically, preserving the refresh counter."""        async with self._lock:            previous = self._accounts.get(state.bookmaker)            self._accounts[state.bookmaker] = StateEntry(                value=state,                refreshed_at=utc_now(),                refreshed_monotonic=time.monotonic(),                refresh_count=(previous.refresh_count + 1) if previous else 1,            )    async def set_active_bets(self, bookmaker: LinkedBookmaker, bets: Sequence[BetRecord]) -> None:        async with self._lock:            previous = self._active_bets.get(bookmaker)            self._active_bets[bookmaker] = StateEntry(                value=tuple(bets),                refreshed_at=utc_now(),                refreshed_monotonic=time.monotonic(),                refresh_count=(previous.refresh_count + 1) if previous else 1,            )    async def set_profile(self, profile: BettorProfile) -> None:        async with self._lock:            previous = self._profiles.get(profile.profile_id)            self._profiles[profile.profile_id] = StateEntry(                value=profile,                refreshed_at=utc_now(),                refreshed_monotonic=time.monotonic(),                refresh_count=(previous.refresh_count + 1) if previous else 1,            )    async def set_modifiers(self, modifiers: Sequence[ProbabilityModifier]) -> None:        async with self._lock:            self._modifiers = tuple(modifiers)    async def set_realized_pnl_today_paise(        self, bookmaker: LinkedBookmaker, pnl_paise: int    ) -> None:        """Record today's settled P&L in exact integer paise.        Consumed by the Twin's loss-budget check, so a float here would leak        rounding error directly into a hard capital constraint.        """        if isinstance(pnl_paise, bool) or not isinstance(pnl_paise, int):            msg = f"pnl_paise must be an int in paise, got {type(pnl_paise).__name__}"            raise ValueError(msg)        async with self._lock:            self._realized_pnl_today_paise[bookmaker] = pnl_paise    def health(self, *, now: datetime | None = None) -> dict[str, object]:        """Cache health for the dashboard and for readiness probes."""        moment = now or utc_now()        return {            "is_warm": self.is_warm,            "profiles": len(self._profiles),            "active_modifiers": len([m for m in self._modifiers if m.is_active(now=moment)]),            "accounts": {                bookmaker.value: {                    "age_seconds": round(entry.age_seconds(now=moment), 3),                    "refresh_count": entry.refresh_count,                    "realized_balance_paise": entry.value.realized_balance_paise,                    "unsettled_exposure_paise": entry.value.unsettled_exposure_paise,                    "is_limited": entry.value.is_limited,                }                for bookmaker, entry in self._accounts.items()            },        }class AccountRefreshDaemon:    """Background L2 poller. Absorbs all bookmaker latency and flakiness.    One independent loop per adapter, so a slow or restricted venue delays only    itself. Each loop is drift-corrected: it measures its own fetch duration on    a monotonic clock and sleeps the remainder of the interval, so a 30 second    cadence with an 8 second fetch sleeps 22 seconds rather than 30 and the    effective cadence does not creep.    """    __slots__ = ("_adapters", "_config", "_health", "_shutdown", "_store")    def __init__(        self,        *,        adapters: Mapping[LinkedBookmaker, AccountStateAdapter],        store: InMemoryStateStore,        config: RefreshConfig,        shutdown: asyncio.Event,    ) -> None:        if not adapters:            msg = "at least one account adapter is required"            raise ValueError(msg)        self._adapters = dict(adapters)        self._store = store        self._config = config        self._shutdown = shutdown        self._health: dict[LinkedBookmaker, RefreshHealth] = {            bookmaker: RefreshHealth(bookmaker=bookmaker) for bookmaker in adapters        }    @property    def health(self) -> Mapping[LinkedBookmaker, RefreshHealth]:        return self._health    async def run(self) -> None:        """Prime the cache once, then poll every adapter until shutdown.        Priming first is deliberate: the orchestrator skips batches while the        cache is cold, so an unprimed start would silently discard the first        interval's worth of opportunities.        """        _log.info(            "refresh_daemon.started",            adapters=[bookmaker.value for bookmaker in self._adapters],            interval_seconds=self._config.interval_seconds,            jitter_fraction=self._config.jitter_fraction,        )        await self.prime()        tasks = [            asyncio.create_task(self._poll_loop(bookmaker), name=f"refresh:{bookmaker.value}")            for bookmaker in self._adapters        ]        try:            await asyncio.gather(*tasks)        except asyncio.CancelledError:            for task in tasks:                task.cancel()            with contextlib.suppress(asyncio.CancelledError):                await asyncio.gather(*tasks, return_exceptions=True)            raise        finally:            _log.info(                "refresh_daemon.stopped",                health=[item.snapshot() for item in self._health.values()],            )    async def prime(self) -> int:        """Fetch every adapter once, concurrently. Returns successes.        Failures are tolerated: a cold cache for one venue must not prevent the        others from becoming usable.        """        results = await asyncio.gather(            *(self._refresh_once(bookmaker) for bookmaker in self._adapters),            return_exceptions=True,        )        succeeded = sum(1 for item in results if item is True)        _log.info(            "refresh_daemon.primed",            succeeded=succeeded,            attempted=len(results),            is_warm=self._store.is_warm,        )        return succeeded    async def _poll_loop(self, bookmaker: LinkedBookmaker) -> None:        """Drift-corrected, jittered poll loop for one adapter."""        while not self._shutdown.is_set():            started = time.monotonic()            await self._refresh_once(bookmaker)            elapsed = time.monotonic() - started            await self._sleep(self._next_delay(bookmaker, elapsed))    def _next_delay(self, bookmaker: LinkedBookmaker, elapsed: float) -> float:        """Remaining interval, expanded exponentially while failing.        Backoff doubles per consecutive failure up to the ceiling. A restricted        or blocked account is polled slowly rather than continuously, because        continued attempts accelerate the restriction.        """        health = self._health[bookmaker]        base = self._config.interval_seconds        if health.consecutive_failures:            base = min(                base * (2.0 ** min(health.consecutive_failures, 10)),                self._config.max_backoff_seconds,            )        jitter = base * self._config.jitter_fraction        target = base + random.uniform(-jitter, jitter)        return max(target - elapsed, 0.0)    async def _sleep(self, seconds: float) -> None:        """Interruptible sleep so shutdown is not delayed by a whole interval."""        if seconds <= 0.0:            return        with contextlib.suppress(TimeoutError, asyncio.TimeoutError):            await asyncio.wait_for(self._shutdown.wait(), timeout=seconds)    async def _refresh_once(self, bookmaker: LinkedBookmaker) -> bool:        """Refresh one adapter. Never raises; records health instead."""        adapter = self._adapters[bookmaker]        health = self._health[bookmaker]        log = _log.bind(bookmaker=bookmaker.value)        try:            state = await asyncio.wait_for(                adapter.fetch_account_state(),                timeout=self._config.fetch_timeout_seconds,            )            await self._store.set_account_state(state)            if self._config.include_active_bets:                bets = await asyncio.wait_for(                    adapter.fetch_active_bets(),                    timeout=self._config.fetch_timeout_seconds,                )                await self._store.set_active_bets(bookmaker, bets)        except asyncio.CancelledError:            raise        except TimeoutError:            self._record_failure(health, "timeout", log)            return False        except TransientIntelligenceError as exc:            self._record_failure(health, f"transient:{type(exc).__name__}", log)            return False        except (AccountUnavailableError, StaleAccountStateError) as exc:            self._record_failure(health, f"unavailable:{type(exc).__name__}", log)            return False        except ReconciliationBreachError as exc:            # A reconciliation break is an incident, not a refresh failure. The            # previous snapshot is deliberately left in place so the Twin's own            # staleness gate ages it out rather than trading on suspect data.            health.total_failures += 1            health.consecutive_failures += 1            health.last_error = "reconciliation_breach"            log.error(                "refresh_daemon.reconciliation_breach",                discrepancy_paise=exc.discrepancy_paise,                detail="halt placement and investigate; stale snapshot retained",            )            return False        except IntelligenceError as exc:            self._record_failure(health, f"adapter:{type(exc).__name__}", log)            return False        except Exception:            health.total_failures += 1            health.consecutive_failures += 1            health.last_error = "unexpected"            log.error("refresh_daemon.unexpected_failure", exc_info=True)            return False        was_quarantined = health.is_quarantined        health.total_refreshes += 1        health.consecutive_failures = 0        health.last_error = None        health.last_success_monotonic = time.monotonic()        health.is_quarantined = False        if was_quarantined:            log.info("refresh_daemon.recovered", total_refreshes=health.total_refreshes)        log.debug(            "refresh_daemon.refreshed",            realized_balance_paise=state.realized_balance_paise,            unsettled_exposure_paise=state.unsettled_exposure_paise,            open_bet_count=state.open_bet_count,            is_limited=state.is_limited,        )        return True    def _record_failure(        self, health: RefreshHealth, error: str, log: structlog.stdlib.BoundLogger    ) -> None:        health.total_failures += 1        health.consecutive_failures += 1        health.last_error = error        if (            not health.is_quarantined            and health.consecutive_failures >= self._config.quarantine_after_failures        ):            health.is_quarantined = True            log.error(                "refresh_daemon.quarantined",                consecutive_failures=health.consecutive_failures,                error=error,                detail="polling reduced to the backoff ceiling",            )        else:            log.warning(                "refresh_daemon.refresh_failed",                consecutive_failures=health.consecutive_failures,                error=error,            )